__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEGAL",{enumerable:!0,get:function(){return k}});const l='\xd6mer Zafer Af\u015far',n='ustamiyolla@gmail.com',t='\u0130stanbul',s='Ustam\u0131 Yolla',k={kvkk:{title:'KVKK Ayd\u0131nlatma Metni',updated:'19 Kas\u0131m 2026',sections:[{h:'Veri sorumlusu',p:`6698 say\u0131l\u0131 Ki\u015fisel Verilerin Korunmas\u0131 Kanunu ("KVKK") kapsam\u0131nda ki\u015fisel verileriniz, veri sorumlusu s\u0131fat\u0131yla ${l} ("Ustam\u0131 Yolla") taraf\u0131ndan a\u015fa\u011f\u0131da a\xe7\u0131klanan \u015fekilde i\u015flenmektedir.`},{h:'\u0130\u015flenen veriler',p:'Kimlik (ad, soyad), ileti\u015fim (e-posta adresi ve telefon numaras\u0131), adres ve konum, i\u015flem bilgileri (talepler, fiyat teklifleri, \xf6deme kay\u0131tlar\u0131, de\u011ferlendirmeler), mesajlar, ekledi\u011finiz foto\u011fraflar. Usta hesaplar\u0131nda ayr\u0131ca kimlik belgesi g\xf6r\xfcnt\xfcs\xfc, adli sicil kayd\u0131, mesleki yeterlilik belgesi (varsa), i\u015f foto\u011fraflar\u0131 ve banka hesap (IBAN) bilgisi i\u015flenir. Adli sicil kayd\u0131 KVKK md. 6 kapsam\u0131nda \xf6zel nitelikli ki\u015fisel veridir; yaln\u0131zca ustan\u0131n a\xe7\u0131k r\u0131zas\u0131yla, m\xfc\u015fteri g\xfcvenli\u011fi amac\u0131yla ba\u015fvurunun de\u011ferlendirilmesi i\xe7in i\u015flenir, sadece yetkili ekip \xfcyeleri g\xf6r\xfcr ve hesap kapat\u0131ld\u0131\u011f\u0131nda silinir. Kart numaran\u0131z\u0131n tamam\u0131 Ustam\u0131 Yolla taraf\u0131ndan saklanmaz; kart i\u015flemleri lisansl\u0131 \xf6deme kurulu\u015fu taraf\u0131ndan y\xfcr\xfct\xfcl\xfcr.'},{h:'\u0130\u015fleme ama\xe7lar\u0131',p:'Hesab\u0131n\u0131z\u0131n olu\u015fturulmas\u0131 ve do\u011frulanmas\u0131; usta ile m\xfc\u015fterinin e\u015fle\u015ftirilmesi; talebin ustaya iletilmesi ve i\u015f s\xfcrecinin y\xfcr\xfct\xfclmesi; \xf6deme, iade ve komisyon i\u015flemleri; ustalar\u0131n kimlik ve yeterlilik kontrol\xfc; m\xfc\u015fteri hizmetleri ve \u015fik\xe2yetlerin \xe7\xf6z\xfcm\xfc; doland\u0131r\u0131c\u0131l\u0131\u011f\u0131n \xf6nlenmesi; yasal y\xfck\xfcml\xfcl\xfcklerin yerine getirilmesi.'},{h:'Hukuki sebepler',p:'KVKK m.5/2-c uyar\u0131nca s\xf6zle\u015fmenin kurulmas\u0131 ve ifas\u0131, m.5/2-\xe7 uyar\u0131nca hukuki y\xfck\xfcml\xfcl\xfcklerin yerine getirilmesi, m.5/2-f uyar\u0131nca me\u015fru menfaat. Konum verisi ve bildirimler i\xe7in a\xe7\u0131k r\u0131zan\u0131z al\u0131n\u0131r; r\u0131zan\u0131z\u0131 telefon ayarlar\u0131ndan her zaman geri \xe7ekebilirsiniz.'},{h:'Aktar\u0131m',p:'Adresiniz, ad\u0131n\u0131z ve telefon numaran\u0131z yaln\u0131zca talebinizi kabul eden ustaya, i\u015f s\xfcresince g\xf6sterilir. Veriler; altyap\u0131 hizmeti ald\u0131\u011f\u0131m\u0131z bulut sa\u011flay\u0131c\u0131lar\u0131na (yurt d\u0131\u015f\u0131nda bulunabilir), \xf6deme kurulu\u015funa, e-posta, SMS ve bildirim sa\u011flay\u0131c\u0131lar\u0131na ve talep halinde yetkili kamu kurumlar\u0131na aktar\u0131labilir.'},{h:'Saklama s\xfcresi',p:'Veriler hesab\u0131n\u0131z a\xe7\u0131k oldu\u011fu s\xfcrece ve ilgili mevzuatta \xf6ng\xf6r\xfclen s\xfcreler boyunca (\xf6r. ticari ve vergisel kay\u0131tlar i\xe7in 10 y\u0131l) saklan\u0131r, s\xfcre sonunda silinir veya anonim hale getirilir.'},{h:'Haklar\u0131n\u0131z',p:`KVKK m.11 uyar\u0131nca verilerinizin i\u015flenip i\u015flenmedi\u011fini \xf6\u011frenme, bilgi talep etme, d\xfczeltilmesini veya silinmesini isteme, aktar\u0131ld\u0131\u011f\u0131 ki\u015fileri bilme ve itiraz etme haklar\u0131na sahipsiniz. Ba\u015fvurular\u0131n\u0131z\u0131 ${n} adresine iletebilirsiniz. Ba\u015fvurular en ge\xe7 30 g\xfcn i\xe7inde yan\u0131tlan\u0131r.`}]},gizlilik:{title:'Gizlilik Politikas\u0131',updated:'19 Kas\u0131m 2026',sections:[{h:'K\u0131saca',p:'Bilgilerinizi yaln\u0131zca usta \xe7a\u011f\u0131rma hizmetini sunmak i\xe7in kullan\u0131r\u0131z. Bilgilerinizi satmay\u0131z, reklam amac\u0131yla payla\u015fmay\u0131z.'},{h:'E-posta ve telefon numaras\u0131',p:'Giri\u015f, e-posta adresinize g\xf6nderilen tek kullan\u0131ml\u0131k kodla yap\u0131l\u0131r. Telefon numaran\u0131z kay\u0131t s\u0131ras\u0131nda al\u0131n\u0131r ve usta ile ileti\u015fim i\xe7in kullan\u0131l\u0131r. Numaran\u0131z yaln\u0131zca i\u015fi kabul eden ustaya, i\u015f devam etti\u011fi s\xfcrece g\xf6r\xfcn\xfcr; i\u015f bitince ya da iptal olunca gizlenir.'},{h:'Konum',p:'Adres eklerken konumunuzu kullanman\u0131za izin veririz; bu iste\u011fe ba\u011fl\u0131d\u0131r. Ustalar yaln\u0131zca bir i\u015f i\xe7in yoldayken ve uygulama a\xe7\u0131kken konumlar\u0131n\u0131 o i\u015fin m\xfc\u015fterisiyle payla\u015f\u0131r.'},{h:'Foto\u011fraflar ve belgeler',p:'Talebe ekledi\u011finiz foto\u011fraflar\u0131 yaln\u0131zca se\xe7ti\u011finiz usta g\xf6r\xfcr. Ustalar\u0131n kimlik ve meslek belgeleri yaln\u0131zca Ustam\u0131 Yolla ekibi taraf\u0131ndan do\u011frulama i\xe7in g\xf6r\xfcl\xfcr, m\xfc\u015fterilere g\xf6sterilmez.'},{h:'\xd6deme bilgileri',p:'Kart bilgileri lisansl\u0131 \xf6deme kurulu\u015fu taraf\u0131ndan i\u015flenir. Uygulamada kart\u0131n yaln\u0131zca son 4 hanesi g\xf6sterilir.'},{h:'Bildirimler',p:'\u0130\u015finizle ilgili bildirimler g\xf6ndeririz (usta kabul etti, usta yolda, fiyat teklifi vb.). Bildirimleri telefon ayarlar\u0131ndan kapatabilirsiniz.'},{h:'Hesab\u0131n silinmesi',p:`Hesab\u0131n\u0131z\u0131 uygulamadaki Profil > Bilgilerim > Hesab\u0131m\u0131 sil ad\u0131m\u0131yla diledi\u011finiz an silebilir ya da ${n} adresinden isteyebilirsiniz. Ad\u0131n\u0131z, telefonunuz, e-postan\u0131z, adreslerin ve kartlar\u0131n\u0131z silinir; tamamlanan i\u015f ve \xf6deme kay\u0131tlar\u0131 yasal saklama s\xfcresi boyunca kimli\u011finiz gizlenerek tutulur.`}]},kullanim:{title:'Kullan\u0131m Ko\u015fullar\u0131',updated:'19 Kas\u0131m 2026',sections:[{h:'Hizmet',p:'Ustam\u0131 Yolla, ev tamir ve bak\u0131m i\u015fleri i\xe7in m\xfc\u015fterileri ba\u011f\u0131ms\u0131z ustalarla bulu\u015fturan bir arac\u0131 platformdur. \u0130\u015fi ustan\u0131n kendisi yapar; Ustam\u0131 Yolla i\u015fin taraf\u0131 de\u011fildir ancak kay\u0131tl\u0131 ustalar\u0131n kimlik ve belge kontrol\xfcn\xfc yapar.'},{h:'Talep ve ke\u015fif \xfccreti',p:'Usta \xe7a\u011f\u0131r\u0131rken kay\u0131tl\u0131 bir kart se\xe7ersiniz. Ustan\u0131n belirledi\u011fi ke\u015fif \xfccreti, usta talebinizi kabul etti\u011fi anda bu karttan tahsil edilir; usta kabul etmezse \xfccret al\u0131nmaz. Ke\u015fif \xfccreti, ustan\u0131n adresinize gelip sorunu tespit etmesinin bedelidir.'},{h:'Lansman d\xf6nemi ve \xf6deme',p:'Lansman d\xf6neminde (Platform komisyon ba\u015flang\u0131\xe7 tarihini duyurana kadar) Platform hi\xe7bir i\u015ften komisyon almaz ve uygulama \xfczerinden \xf6deme tahsil etmez; ke\u015fif \xfccreti ve onaylanan i\u015f bedeli do\u011frudan ustaya \xf6denir, tutarlar uygulamada kay\u0131tl\u0131 kal\u0131r. Komisyon d\xf6nemi ba\u015flad\u0131\u011f\u0131nda b\xfct\xfcn \xf6demeler yaln\u0131zca uygulama \xfczerinden kartla yap\u0131l\u0131r ve nakit \xf6deme kabul edilmez. Ustaya yaln\u0131zca uygulamada onaylad\u0131\u011f\u0131n\u0131z tutar\u0131 \xf6deyin; fazlas\u0131 istenirse Yard\u0131m b\xf6l\xfcm\xfcnden bildirin.'},{h:'Fiyat teklifi',p:'Usta ke\u015fiften sonra i\u015f\xe7ilik ve malzeme bedelini uygulamaya girer. Siz onaylamadan i\u015fe ba\u015flanmaz. Kartla \xf6demede tutar i\u015f tamamland\u0131\u011f\u0131nda \xe7ekilir. Usta i\u015fi bitirip uygulamada kapatmazsa i\u015fi siz de onaylayarak kapatabilirsiniz.'},{h:'Ustam\u0131 Yolla g\xfcvencesi',p:'Yaln\u0131zca uygulamada onaylanan ve uygulama \xfczerinden kaydedilen i\u015fler g\xfcvence kapsam\u0131ndad\u0131r. Usta uygulama d\u0131\u015f\u0131nda \xf6deme ya da onaylanan fiyattan fazlas\u0131n\u0131 isterse uygulamadaki Sorun bildir b\xf6l\xfcm\xfcnden bize haber verin. Uygulama d\u0131\u015f\u0131nda yap\u0131lan \xf6demeler ve anla\u015fmalar i\xe7in Platform sorumluluk kabul etmez. Uygulamada tamamlanan i\u015flerde \xe7\u0131kan sorunlar i\xe7in i\u015f tamamland\u0131ktan sonra 30 g\xfcn i\xe7inde uygulamadan garanti talebi a\xe7\u0131labilir; Platform, ustayla birlikte sorunun giderilmesine arac\u0131l\u0131k eder. Kapsam ve istisnalar 30 G\xfcn G\xfcvence metninde yaz\u0131l\u0131d\u0131r.'},{h:'De\u011ferlendirmeler',p:'Yaln\u0131zca uygulama \xfczerinden tamamlanan i\u015fler i\xe7in de\u011ferlendirme yap\u0131labilir. Hakaret, ki\u015fisel bilgi veya ger\xe7e\u011fe ayk\u0131r\u0131 i\xe7erik i\xe7eren yorumlar kald\u0131r\u0131labilir.'},{h:'Yasak davran\u0131\u015flar',p:'Sahte hesap a\xe7mak, ba\u015fkas\u0131 ad\u0131na i\u015flem yapmak, ustay\u0131 platform d\u0131\u015f\u0131nda \xf6deme yapmaya zorlamak ve taciz edici mesaj g\xf6ndermek yasakt\u0131r; bu durumda hesap ask\u0131ya al\u0131nabilir.'},{h:'Sorumluluk',p:'Ustan\u0131n yapt\u0131\u011f\u0131 i\u015ften do\u011fan sorunlarda \xf6nce ustayla, \xe7\xf6z\xfclemezse destek ekibimizle ileti\u015fime ge\xe7in. Ustam\u0131 Yolla \u015fik\xe2yetleri inceler ve gerekirse ustan\u0131n hesab\u0131n\u0131 ask\u0131ya al\u0131r.'},{h:'\u0130leti\u015fim',p:`Soru ve \u015fik\xe2yetleriniz i\xe7in: ${n}`}]},iptal:{title:'\u0130ptal ve \u0130ade Ko\u015fullar\u0131',updated:'19 Kas\u0131m 2026',sections:[{h:'Usta kabul etmeden iptal',p:'Usta talebi kabul etmeden iptal ederseniz ya da usta talebi alamazsa kart\u0131n\u0131zdan hi\xe7bir \xfccret \xe7ekilmez.'},{h:'Usta yola \xe7\u0131kmadan iptal',p:'Usta kabul ettikten sonra ancak yola \xe7\u0131kmadan iptal ederseniz ke\u015fif \xfccreti tamamen iade edilir.'},{h:'Usta yola \xe7\u0131kt\u0131ktan sonra',p:'Usta yola \xe7\u0131kt\u0131ktan sonra talep uygulamadan iptal edilemez. Usta ke\u015ffi yapt\u0131ktan sonra fiyat teklifini reddederseniz ke\u015fif \xfccreti ustaya \xf6denir, iade edilmez.'},{h:'\u0130ade s\xfcresi',p:'\u0130adeler ayn\u0131 karta yap\u0131l\u0131r. Tutar\u0131n hesab\u0131n\u0131za ge\xe7mesi bankan\u0131za ba\u011fl\u0131 olarak 1-7 i\u015f g\xfcn\xfc s\xfcrebilir.'},{h:'\u0130\u015f\xe7ilik garantisi',p:'Usta yapt\u0131\u011f\u0131 i\u015f\xe7ilik i\xe7in 30 g\xfcn garanti verir (ayr\u0131nt\u0131lar 30 G\xfcn G\xfcvence metninde). Ayn\u0131 ar\u0131za bu s\xfcrede tekrarlarsa uygulama \xfczerinden ustaya ula\u015fabilir ya da destek ekibimize yazabilirsiniz.'}]},usta:{title:'Usta Hizmet S\xf6zle\u015fmesi',updated:'19 Kas\u0131m 2026',sections:[{h:'Taraflar',p:`Bu s\xf6zle\u015fme ${l} ("Platform") ile Platform'a usta olarak kay\u0131t olan ki\u015fi ("Usta") aras\u0131ndad\u0131r. Usta, Platform'un \xe7al\u0131\u015fan\u0131 de\u011fildir; ba\u011f\u0131ms\u0131z olarak hizmet verir.`},{h:'Ba\u015fvuru ve belgeler',p:'Usta, kimlik belgesini ve e-Devlet \xfczerinden ald\u0131\u011f\u0131 g\xfcncel adli sicil kayd\u0131n\u0131 y\xfckler. Mesleki yeterlilik veya ustal\u0131k belgesi varsa onu da y\xfckler; yoksa yapt\u0131\u011f\u0131 i\u015flerden en az 3 foto\u011fraf y\xfckler ve Platform ba\u015fvuruyu bu foto\u011fraflara g\xf6re de\u011ferlendirir. Belgelerin sahte \xe7\u0131kmas\u0131 halinde hesap kapat\u0131l\u0131r. Platform ba\u015fvuruyu onaylamadan Usta m\xfc\u015fterilere g\xf6r\xfcnmez. Platform, adli sicil kayd\u0131n\u0131n yenilenmesini d\xf6nemsel olarak isteyebilir.'},{h:'Ke\u015fif \xfccreti ve fiyat',p:'Usta ke\u015fif \xfccretini kendisi belirler ve profilinden de\u011fi\u015ftirebilir. \u0130\u015f bedelini ke\u015fiften sonra uygulamaya kalem kalem girer. M\xfc\u015fterinin onaylad\u0131\u011f\u0131 fiyat\u0131n \xfczerinde \xfccret talep edilemez.'},{h:'M\xfc\u015fteri bilgileri',p:'M\xfc\u015fterinin a\xe7\u0131k adresi ve telefon numaras\u0131 Usta i\u015fi kabul etti\u011finde g\xf6sterilir ve i\u015f bitince gizlenir. Uygulama i\xe7i mesajlarda telefon numaras\u0131 ve IBAN payla\u015f\u0131m\u0131 otomatik olarak gizlenir. Usta, Platform \xfczerinden tan\u0131\u015ft\u0131\u011f\u0131 m\xfc\u015fteriyle sonraki i\u015fleri de Platform \xfczerinden y\xfcr\xfct\xfcr.'},{h:'Lansman d\xf6nemi',p:'Platform, komisyon ba\u015flang\u0131\xe7 tarihini en az 30 g\xfcn \xf6nceden uygulama i\xe7i bildirimle duyurana kadar Usta\'dan hi\xe7bir komisyon ya da \xfccret almaz. Bu d\xf6nemde m\xfc\u015fteri ke\u015fif \xfccretini ve onaylanan i\u015f bedelini do\u011frudan Usta\'ya \xf6der; Usta yaln\u0131zca uygulamada yaz\u0131l\u0131 tutar\u0131 alabilir.'},{h:'Komisyon',p:'Komisyon d\xf6nemi ba\u015flad\u0131ktan sonra a\xe7\u0131lan i\u015flerde Platform, Usta\'n\u0131n ke\u015fif \xfccretinden %25 komisyon al\u0131r; komisyon \xf6deme Usta\'ya aktar\u0131lmadan \xf6nce d\xfc\u015f\xfcl\xfcr. \u0130\u015f\xe7ilik ve malzeme bedelinden komisyon al\u0131nmaz. Bu d\xf6nemde b\xfct\xfcn \xf6demeler uygulama \xfczerinden kartla yap\u0131l\u0131r, nakit \xf6deme al\u0131namaz. Oranlar ayarlarda belirtilir; de\u011fi\u015fiklik yap\u0131lacaksa Usta\'ya en az 15 g\xfcn \xf6nceden uygulama i\xe7inden bildirilir ve de\u011fi\u015fiklik yaln\u0131zca bildirimden sonra a\xe7\u0131lan i\u015flere uygulan\u0131r. M\xfc\u015fteri fiyat\u0131 reddederse de ke\u015fif \xfccretinden ayn\u0131 oranda komisyon al\u0131n\u0131r.'},{h:'\xd6demeler',p:'Kartla tahsil edilen tutarlardan komisyon d\xfc\u015f\xfclerek kalan k\u0131s\u0131m her Cuma Usta\'n\u0131n kay\u0131tl\u0131 IBAN\'\u0131na aktar\u0131l\u0131r.'},{h:'Usta Pro paketi',p:'Usta, uygulamada g\xf6sterilen ayl\u0131k \xfccreti (ba\u015flang\u0131\xe7ta 300 TL) kay\u0131tl\u0131 kart\u0131yla \xf6deyerek 30 g\xfcn boyunca hi\xe7bir i\u015finden komisyon kesilmeden \xe7al\u0131\u015fabilir. Paket otomatik yenilenmez. Komisyon d\xf6nemi ba\u015flamadan al\u0131nan paket, komisyonun ba\u015flad\u0131\u011f\u0131 g\xfcnden itibaren i\u015fler. Kullan\u0131lan paket bedeli iade edilmez; Platform kaynakl\u0131 bir sorunda kalan g\xfcn kadar iade yap\u0131l\u0131r.'},{h:'Ayl\u0131k \xe7ark',p:'Usta, bir takvim ay\u0131nda uygulama \xfczerinden tamamlad\u0131\u011f\u0131 her 5 i\u015f i\xe7in bir \xfccretsiz \xe7ark \xe7evirme hakk\u0131 kazan\u0131r. \xc7ark \xfccretsizdir, para ile \xe7evirme hakk\u0131 sat\u0131lmaz ve her \xe7evirme bir \xf6d\xfcl verir: 1 ay komisyonsuz \xe7al\u0131\u015fma, belirli say\u0131da komisyonsuz ya da yar\u0131 komisyonlu i\u015f veya listede bir hafta \xf6ne \xe7\u0131kma. \xd6d\xfcller nakde \xe7evrilemez ve devredilemez. Kullan\u0131lmayan \xe7evirme haklar\u0131 ay sonunda sona erer. Platform d\u0131\u015f\u0131nda yap\u0131lan ya da sahte i\u015flerle kazan\u0131lan \xf6d\xfcller iptal edilir.'},{h:'Davran\u0131\u015f kurallar\u0131',p:'Usta, m\xfc\u015fteriyi Platform d\u0131\u015f\u0131nda \xf6deme yapmaya y\xf6nlendiremez, yapt\u0131\u011f\u0131 i\u015fi uygulamada kaydetmeden \xfccret alamaz; bu kurallara ayk\u0131r\u0131 davranan Usta\'n\u0131n hesab\u0131 uyar\u0131 yap\u0131lmadan kapat\u0131labilir ve bekleyen \xf6demeleri komisyon alacaklar\u0131na mahsup edilir. Usta ayr\u0131ca kabul etti\u011fi i\u015fe zaman\u0131nda gider, gecikmede m\xfc\u015fteriye haber verir, uygulamadan tamamlad\u0131\u011f\u0131 i\u015flerin i\u015f\xe7ili\u011fine 30 g\xfcn garanti verir: kendi i\u015f\xe7ilik kusurundan kaynaklanan sorunu bu s\xfcre i\xe7inde ke\u015fif ve i\u015f\xe7ilik \xfccreti almadan giderir.'},{h:'Ask\u0131ya alma',p:'S\u0131k iptal, d\xfc\u015f\xfck puan, \u015fik\xe2yet veya kurallara ayk\u0131r\u0131l\u0131k halinde Platform Usta\'n\u0131n hesab\u0131n\u0131 ask\u0131ya alabilir.'},{h:'Fesih',p:`Usta diledi\u011fi zaman ${n} adresine yazarak hesab\u0131n\u0131 kapatabilir. A\xe7\u0131k bakiye kapan\u0131\u015f s\u0131ras\u0131nda \xf6denir veya tahsil edilir.`}]},guvence:{title:'30 G\xfcn G\xfcvence',updated:'25 Kas\u0131m 2026',sections:[{h:'K\u0131saca',p:`Uygulama \xfczerinden onaylan\u0131p tamamlanan bir i\u015fte ustan\u0131n i\u015f\xe7ilik kusurundan kaynaklanan bir sorun \xe7\u0131karsa, i\u015f tamamland\u0131ktan sonraki 30 g\xfcn i\xe7inde uygulamadan garanti talebi a\xe7abilirsiniz. ${s} talebinizi ustayla birlikte takip eder ve ustan\u0131n i\u015f\xe7ilik kusurundan kaynaklanan sorunun \xfccretsiz giderilmesini sa\u011flar.`},{h:'Kimler yararlan\u0131r?',p:'Ustay\u0131 uygulamadan \xe7a\u011f\u0131ran, fiyat\u0131 uygulamada onaylayan ve i\u015f uygulamada "tamamland\u0131" olarak kapanan m\xfc\u015fteriler. Uygulama d\u0131\u015f\u0131nda anla\u015f\u0131lan i\u015fler, uygulamada onaylanmam\u0131\u015f ek i\u015fler ve uygulamada kayd\u0131 olmayan \xf6demeler g\xfcvence kapsam\u0131nda de\u011fildir.'},{h:'Neleri kapsar?',p:'Ustan\u0131n yapt\u0131\u011f\u0131 i\u015fle do\u011frudan ilgili i\u015f\xe7ilik kusurlar\u0131: ayn\u0131 ar\u0131zan\u0131n k\u0131sa s\xfcrede tekrarlamas\u0131, i\u015fin eksik ya da hatal\u0131 yap\u0131lmas\u0131 (\xf6r. gev\u015fek ba\u011flant\u0131, ka\xe7ak yapan ek yeri, yanl\u0131\u015f ba\u011flanan hat), ustan\u0131n i\u015fi yaparken verdi\u011fi ve i\u015fle ilgili hasar.'},{h:'Neleri kapsamaz?',p:'Ustan\u0131n takt\u0131\u011f\u0131 \xfcr\xfcn ya da par\xe7an\u0131n kendi ar\u0131zas\u0131 (bu durumda \xfcr\xfcn\xfcn \xfcretici veya sat\u0131c\u0131 garantisi ge\xe7erlidir; malzeme fi\u015fi uygulamada saklan\u0131r); kullan\u0131m hatas\u0131, darbe, su bask\u0131n\u0131, elektrik dalgalanmas\u0131 gibi d\u0131\u015f etkenler; i\u015ften sonra ba\u015fka birinin m\xfcdahalesi; do\u011fal a\u015f\u0131nma ve sarf malzemeleri; usta taraf\u0131ndan i\u015f \xf6ncesinde uygulamada yaz\u0131l\u0131 olarak bildirilmi\u015f riskler; yap\u0131lan i\u015fle ilgisi olmayan yeni ar\u0131zalar.'},{h:'Nas\u0131l ba\u015fvurulur?',p:'Uygulamada ilgili i\u015fin ekran\u0131ndaki "Garanti talebi a\xe7" ba\u011flant\u0131s\u0131ndan ya da Profil > Yard\u0131m ve destek b\xf6l\xfcm\xfcnden, i\u015f tamamland\u0131ktan sonraki 30 g\xfcn i\xe7inde ba\u015fvurun. Sorunu k\u0131saca anlat\u0131n, m\xfcmk\xfcnse foto\u011fraf ekleyin.'},{h:'S\xfcre\xe7',p:`1) Talebiniz en ge\xe7 2 i\u015f g\xfcn\xfc i\xe7inde yan\u0131tlan\u0131r. 2) Ekibimiz ustaya ula\u015f\u0131r ve sorunun i\u015f\xe7ilikten kaynaklan\u0131p kaynaklanmad\u0131\u011f\u0131n\u0131 birlikte de\u011ferlendirir. 3) \u0130\u015f\xe7ilik kusuru varsa usta, uygun bir zamanda gelip sorunu ke\u015fif ve i\u015f\xe7ilik \xfccreti almadan giderir. 4) Usta makul s\xfcrede (hedef 7 g\xfcn) gelmez ya da sorunu gidermezse ${s} size ba\u015fka bir usta bulmaya yard\u0131mc\u0131 olur, ilk usta hakk\u0131nda hesab\u0131n ask\u0131ya al\u0131nmas\u0131na kadar varan i\u015flem yapar ve sizi yasal ba\u015fvuru yollar\u0131n\u0131z hakk\u0131nda bilgilendirir.`},{h:"Platformun rol\xfc",p:`${s} hizmeti bizzat vermez; m\xfc\u015fteri ile ustay\u0131 bulu\u015fturan arac\u0131 hizmet sa\u011flay\u0131c\u0131d\u0131r. \u0130\u015fin kendisinden ve i\u015f\xe7ilik garantisinden usta sorumludur. ${s} garanti s\xfcrecini takip eder, taraflar aras\u0131nda arabuluculuk yapar ve kurallara uymayan ustalara yapt\u0131r\u0131m uygular. Bu g\xfcvence ek bir hizmettir; parasal tazminat taahh\xfcd\xfc i\xe7ermez.`},{h:'Yasal haklar\u0131n\u0131z sakl\u0131d\u0131r',p:'30 G\xfcn G\xfcvence, 6502 say\u0131l\u0131 T\xfcketicinin Korunmas\u0131 Hakk\u0131nda Kanun ve ilgili mevzuattan do\u011fan haklar\u0131n\u0131z\u0131 daraltmaz veya kald\u0131rmaz. Ay\u0131pl\u0131 hizmet h\xe2linde yasal haklar\u0131n\u0131z\u0131 kullanabilir, t\xfcketici hakem heyetine veya t\xfcketici mahkemesine ba\u015fvurabilirsiniz.'},{h:'\u0130leti\u015fim',p:`Sorular\u0131n\u0131z i\xe7in ${n} adresine yazabilirsiniz.`}]},hakkimizda:{title:'Hakk\u0131m\u0131zda',updated:'24 Kas\u0131m 2026',sections:[{h:`${s} nedir?`,p:`${s}, \u0130stanbul'da ev tamir, tadilat ve bak\u0131m i\u015fleri i\xe7in m\xfc\u015fterileri kimli\u011fi ve mesleki belgesi kontrol edilmi\u015f ba\u011f\u0131ms\u0131z ustalarla bulu\u015fturan bir mobil uygulamad\u0131r. M\xfc\u015fteri ihtiyac\u0131n\u0131 yazar, ustay\u0131 se\xe7er; usta ke\u015fiften sonra fiyat\u0131 uygulamaya girer ve m\xfc\u015fteri onaylamadan i\u015f ba\u015flamaz.`},{h:'Nas\u0131l \xe7al\u0131\u015f\u0131r?',p:'Ustalar kendi ke\u015fif \xfccretlerini belirler. \u0130\u015f bedeli ke\u015fiften sonra kalem kalem uygulamaya girilir ve m\xfc\u015fteri onaylamadan i\u015f ba\u015flamaz. Lansman d\xf6neminde komisyon al\u0131nmaz ve \xf6demeler do\u011frudan ustaya yap\u0131l\u0131r; komisyon d\xf6nemi ba\u015flad\u0131\u011f\u0131nda b\xfct\xfcn \xf6demeler uygulamadan kartla yap\u0131l\u0131r. Uygulamada tamamlanan i\u015fler 30 g\xfcn g\xfcvence kapsam\u0131ndad\u0131r.'},{h:'Hizmet sa\u011flay\u0131c\u0131',p:`${s} uygulamas\u0131n\u0131 ${l} i\u015fletir. Adres: ${t}. E-posta: ${n}. Destek: uygulama i\xe7i Yard\u0131m ve destek b\xf6l\xfcm\xfc.`}]},iletisim:{title:'\u0130leti\u015fim',updated:'24 Kas\u0131m 2026',sections:[{h:'Hizmet sa\u011flay\u0131c\u0131',p:l},{h:'Adres',p:t},{h:'Destek',p:'Uygulamadaki Profil > Yard\u0131m ve destek b\xf6l\xfcm\xfcnden bize yazabilirsiniz.'},{h:'E-posta',p:n},{h:'Uygulama i\xe7inden',p:'Uygulamadaki Profil > Yard\u0131m ve destek b\xf6l\xfcm\xfcnden bize yazabilir, i\u015flerinizle ilgili garanti talebi a\xe7abilirsiniz. Mesajlara mesai saatleri i\xe7inde en ge\xe7 1 i\u015f g\xfcn\xfc i\xe7inde d\xf6n\xfc\u015f yap\u0131l\u0131r.'}]},onbilgi:{title:'\xd6n Bilgilendirme Formu',updated:'24 Kas\u0131m 2026',sections:[{h:'1. Hizmet sa\u011flay\u0131c\u0131',p:`Ad Soyad: ${l}. Adres: ${t}. E-posta: ${n}. Destek: uygulama i\xe7i Yard\u0131m ve destek b\xf6l\xfcm\xfc.`},{h:'2. Hizmetin konusu',p:`${s} mobil uygulamas\u0131 \xfczerinden, m\xfc\u015fterinin se\xe7ti\u011fi ba\u011f\u0131ms\u0131z usta taraf\u0131ndan m\xfc\u015fterinin adresinde ke\u015fif yap\u0131lmas\u0131 ve m\xfc\u015fterinin onaylamas\u0131 halinde tamir, tadilat, montaj veya bak\u0131m i\u015finin yap\u0131lmas\u0131d\u0131r. Platform, m\xfc\u015fteri ile usta aras\u0131nda arac\u0131l\u0131k eder ve \xf6demeleri lisansl\u0131 \xf6deme kurulu\u015fu arac\u0131l\u0131\u011f\u0131yla tahsil eder.`},{h:'3. Fiyat ve \xf6deme',p:'Ke\u015fif \xfccreti ustan\u0131n profilinde ve talep ekran\u0131nda KDV dahil olarak g\xf6sterilir \u0130\u015f\xe7ilik ve malzeme bedeli ke\u015fiften sonra kalem kalem uygulamada g\xf6sterilir; m\xfc\u015fteri onaylamadan i\u015f ba\u015flamaz ve bu bedel i\xe7in \xf6deme yap\u0131lmaz. Lansman d\xf6neminde (Platform komisyon ba\u015flang\u0131\xe7 tarihini duyurana kadar) Platform hi\xe7bir i\u015ften komisyon almaz ve uygulama \xfczerinden \xf6deme tahsil etmez; ke\u015fif \xfccreti ve onaylanan i\u015f bedeli do\u011frudan ustaya \xf6denir, tutarlar uygulamada kay\u0131tl\u0131 kal\u0131r. Komisyon d\xf6nemi ba\u015flad\u0131\u011f\u0131nda b\xfct\xfcn \xf6demeler yaln\u0131zca uygulama \xfczerinden kartla yap\u0131l\u0131r ve nakit \xf6deme kabul edilmez. Komisyon d\xf6neminde ke\u015fif \xfccreti usta talebi kabul etti\u011finde, i\u015f bedeli i\u015f tamamland\u0131\u011f\u0131nda m\xfc\u015fterinin kart\u0131ndan tahsil edilir. Kampanya indirimleri \xf6deme ekran\u0131nda g\xf6sterilir.'},{h:'4. Hizmetin ifas\u0131',p:'Usta, m\xfc\u015fterinin se\xe7ti\u011fi zaman diliminde adrese gelir. Gecikme halinde m\xfc\u015fteriye uygulama \xfczerinden bilgi verir. \u0130\u015fin tamamland\u0131\u011f\u0131 usta ya da m\xfc\u015fteri taraf\u0131ndan uygulamada onaylan\u0131r.'},{h:'5. Cayma hakk\u0131',p:'M\xfc\u015fteri, usta talebi kabul etmeden \xf6nce talebi \xfccretsiz iptal edebilir. Usta kabul ettikten sonra ancak yola \xe7\u0131kmadan iptal edilirse ke\u015fif \xfccreti tamamen iade edilir. Mesafeli S\xf6zle\u015fmeler Y\xf6netmeli\u011fi uyar\u0131nca, cayma s\xfcresi dolmadan m\xfc\u015fterinin onay\u0131yla ifas\u0131na ba\u015flanan hizmetlerde (usta yola \xe7\u0131kt\u0131ktan ve ke\u015fif ba\u015flad\u0131ktan sonra) cayma hakk\u0131 kullan\u0131lamaz. M\xfc\u015fteri ke\u015fiften sonra fiyat\u0131 reddederse yaln\u0131zca ke\u015fif \xfccreti \xf6denmi\u015f olur; i\u015f bedeli al\u0131nmaz.'},{h:'6. \u0130ade',p:'\u0130ade gereken durumlarda tutar, \xf6demenin yap\u0131ld\u0131\u011f\u0131 karta 14 g\xfcn i\xe7inde iade edilir. Kart\u0131n bankas\u0131na ba\u011fl\u0131 olarak tutar\u0131n hesaba yans\u0131mas\u0131 birka\xe7 g\xfcn s\xfcrebilir.'},{h:'7. \u015eik\xe2yet ve itiraz',p:`\u015eik\xe2yetler i\xe7in uygulamadaki Yard\u0131m ve destek b\xf6l\xfcm\xfc ya da ${n} kullan\u0131labilir. M\xfc\u015fteri, Ticaret Bakanl\u0131\u011f\u0131nca her y\u0131l belirlenen parasal s\u0131n\u0131rlar dahilinde yerle\u015fim yerindeki T\xfcketici Hakem Heyetine veya T\xfcketici Mahkemesine ba\u015fvurabilir.`}]},mesafeli:{title:'Mesafeli Hizmet S\xf6zle\u015fmesi',updated:'24 Kas\u0131m 2026',sections:[{h:'Madde 1: Taraflar',p:`Hizmet sa\u011flay\u0131c\u0131 (Platform): ${l}, ${t}, ${n}. M\xfc\u015fteri: ${s} uygulamas\u0131nda kay\u0131tl\u0131, talep olu\u015fturan kullan\u0131c\u0131; bilgileri uygulamadaki hesab\u0131nda yer al\u0131r.`},{h:'Madde 2: Konu',p:`Bu s\xf6zle\u015fme, m\xfc\u015fterinin ${s} uygulamas\u0131 \xfczerinden olu\u015fturdu\u011fu usta talebine ili\u015fkin ke\u015fif ve (onaylanmas\u0131 halinde) i\u015f hizmetinin sat\u0131\u015f\u0131 ve ifas\u0131na ili\u015fkin taraflar\u0131n hak ve y\xfck\xfcml\xfcl\xfcklerini, 6502 say\u0131l\u0131 T\xfcketicinin Korunmas\u0131 Hakk\u0131nda Kanun ve Mesafeli S\xf6zle\u015fmeler Y\xf6netmeli\u011fi h\xfck\xfcmlerine g\xf6re d\xfczenler.`},{h:'Madde 3: Hizmet ve bedel',p:'Hizmetin t\xfcr\xfc, ustan\u0131n ad\u0131, adres, zaman ve ke\u015fif \xfccreti talep an\u0131nda uygulamada g\xf6sterilir. \u0130\u015f\xe7ilik ve malzeme bedeli ke\u015fiften sonra uygulamada m\xfc\u015fterinin onay\u0131na sunulur; m\xfc\u015fteri onaylad\u0131\u011f\u0131nda bu bedel s\xf6zle\u015fmenin par\xe7as\u0131 olur. T\xfcm fiyatlar T\xfcrk Liras\u0131 ve vergiler dahildir.'},{h:'Madde 4: \xd6deme',p:'Lansman d\xf6neminde ke\u015fif \xfccreti ve onaylanan i\u015f bedeli do\u011frudan ustaya \xf6denir; Platform \xf6deme tahsil etmez ve komisyon almaz, tutarlar uygulamada kay\u0131tl\u0131 kal\u0131r. Komisyon d\xf6neminde ke\u015fif \xfccreti usta talebi kabul etti\u011finde, i\u015f bedeli i\u015f tamamland\u0131\u011f\u0131nda lisansl\u0131 \xf6deme kurulu\u015fu arac\u0131l\u0131\u011f\u0131yla m\xfc\u015fterinin kart\u0131ndan tahsil edilir; bu d\xf6nemde nakit \xf6deme kabul edilmez. Kart bilgileri Platform taraf\u0131ndan saklanmaz. M\xfc\u015fteri yaln\u0131zca uygulamada onaylanan tutar\u0131 \xf6der.'},{h:'Madde 5: \u0130fa',p:'Usta, se\xe7ilen zaman diliminde m\xfc\u015fterinin adresine gelir ve onaylanan i\u015fi yapar. Usta Platform\'un \xe7al\u0131\u015fan\u0131 de\u011fildir; i\u015fi ba\u011f\u0131ms\u0131z olarak, kendi mesleki sorumlulu\u011fuyla yapar. Platform, ustan\u0131n kimlik ve mesleki belgelerini kontrol eder ve uygulamada tamamlanan i\u015flerde \xe7\u0131kan sorunlar\u0131n giderilmesine arac\u0131l\u0131k eder.'},{h:'Madde 6: Cayma hakk\u0131',p:'M\xfc\u015fteri, usta talebi kabul etmeden \xf6nce ya da kabul ettikten sonra usta yola \xe7\u0131kmadan \xf6nce talebi uygulamadan iptal edebilir; bu durumda \xf6denen ke\u015fif \xfccreti iade edilir. M\xfc\u015fterinin onay\u0131yla ifas\u0131na ba\u015flanan hizmetlerde (usta yola \xe7\u0131kt\u0131ktan sonra) Mesafeli S\xf6zle\u015fmeler Y\xf6netmeli\u011fi md. 15 uyar\u0131nca cayma hakk\u0131 kullan\u0131lamaz. M\xfc\u015fteri ke\u015fiften sonra fiyat\u0131 reddederse i\u015f bedeli do\u011fmaz; ke\u015fif \xfccreti iade edilmez.'},{h:'Madde 7: G\xfcvence',p:'Uygulamada onaylanan ve tamamlanan i\u015flerde i\u015f tamamland\u0131ktan sonra 30 g\xfcn i\xe7inde uygulamadan garanti talebi a\xe7\u0131labilir. Uygulama d\u0131\u015f\u0131nda yap\u0131lan \xf6demeler ve anla\u015fmalar g\xfcvence kapsam\u0131nda de\u011fildir.'},{h:'Madde 8: Ki\u015fisel veriler',p:'M\xfc\u015fterinin ki\u015fisel verileri KVKK Ayd\u0131nlatma Metni ve Gizlilik Politikas\u0131\'nda belirtilen \u015fekilde i\u015flenir.'},{h:'Madde 9: Uyu\u015fmazl\u0131k',p:'Uyu\u015fmazl\u0131klarda Ticaret Bakanl\u0131\u011f\u0131nca ilan edilen parasal s\u0131n\u0131rlar dahilinde t\xfcketicinin yerle\u015fim yerindeki T\xfcketici Hakem Heyetleri, a\u015fan durumlarda T\xfcketici Mahkemeleri yetkilidir.'},{h:'Madde 10: Y\xfcr\xfcrl\xfck',p:'M\xfc\u015fteri, talebi g\xf6ndermeden \xf6nce \xd6n Bilgilendirme Formu\'nu ve bu s\xf6zle\u015fmeyi okudu\u011funu ve kabul etti\u011fini uygulamada onaylar. S\xf6zle\u015fme, talebin g\xf6nderilmesiyle kurulur ve elektronik ortamda saklan\u0131r; m\xfc\u015fteri diledi\u011fi zaman uygulamadan eri\u015febilir.'}]}}},856,[]);